package com.hbm.machine.radar;
import api.hbm.entity.RadarEntry;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** Source ephemeral external screen: send100 then clear each tick, linked radar refresh sends25 immediately. */
public final class RadarScreenBlockEntity extends BlockEntity implements com.hbm.multiblock.MuffledMachine{public boolean muffled,tilted;@Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}@Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}public final List<RadarEntry> entries=new ArrayList<>();public int refX,refY,refZ,range;public boolean linked;public RadarScreenBlockEntity(BlockPos p,BlockState s){super(RadarContent.SCREEN_ENTITY.get(),p,s);}public static void tick(Level level,BlockPos p,BlockState state,RadarScreenBlockEntity s){if(level instanceof ServerLevel){s.sync(100);s.entries.clear();s.linked=false;}}public void sync(int radius){if(level instanceof ServerLevel server){var packet=getUpdatePacket();for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<radius*radius)player.connection.send(packet);}}@Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();tag.putBoolean("linked",linked);tag.putInt("refX",refX);tag.putInt("refY",refY);tag.putInt("refZ",refZ);tag.putInt("range",range);var list=new net.minecraft.nbt.ListTag();for(var e:entries){var t=new CompoundTag();t.putString("name",e.unlocalizedName);t.putInt("type",e.blipLevel);t.putInt("x",e.posX);t.putInt("y",e.posY);t.putInt("z",e.posZ);t.putString("dimension",e.dim.location().toString());t.putInt("entity",e.entityID);list.add(t);}tag.put("entries",list);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){linked=tag.getBoolean("linked");refX=tag.getInt("refX");refY=tag.getInt("refY");refZ=tag.getInt("refZ");range=tag.getInt("range");entries.clear();for(var value:tag.getList("entries",10)){var t=(CompoundTag)value;var e=new RadarEntry();e.unlocalizedName=t.getString("name");e.blipLevel=t.getInt("type");e.posX=t.getInt("x");e.posY=t.getInt("y");e.posZ=t.getInt("z");e.dim=net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(t.getString("dimension")));e.entityID=t.getInt("entity");entries.add(e);}}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection c,ClientboundBlockEntityDataPacket p,HolderLookup.Provider l){handleUpdateTag(p.getTag(),l);}}
